            username === (process.env.ADMIN_USER ?? 'admin') &&
            password === (process.env.ADMIN_PASS ?? 'changeme') &&
            totpOk
          ) {
            const token = jwt.sign(
              { sub: username, role: 'admin' },
              undefined,
              { expiresIn: 3600 },
            );
            logger.info({ event: 'sign_in', user: username, role: 'admin' }, 'Successful sign-in');
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ token }));
          } else {
            logger.warn({ event: 'sign_in_failure', user: username }, 'Failed sign-in attempt');
            res.writeHead(401, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ error: 'Invalid credentials' }));
          }
        } catch (err) {
          logger.error({ event: 'sign_in_error', err }, 'Error processing login');
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Bad request' }));
        }
      });
    });

    // Guard all other /api routes only when credentials are configured.
    const authEnabled = !!(process.env.ADMIN_PASS || process.env.ADMIN_USER);
    server.middlewares.use('/api', (req, res, next) => {
      if (!authEnabled) return next();
      if (PUBLIC_PATHS.some((p) => req.url === p || req.url?.startsWith(p + '?')))
        return next();

      const raw = extractToken(req);
      if (!raw) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Authentication required' }));
        return;
      }

      try {
        const payload = jwt.verify(raw);
        req.user = payload;
        // Enforce minimum role for all API access.
        requireRole(payload, 'user');
        next();
      } catch (err) {
        logger.warn({ event: 'auth_error', path: req.url, err: err.message }, 'API authentication failure');
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: err.message ?? 'Unauthorized' }));
      }
    });
  };

  const installWithErrorHandler = (server) => {
    install(server);
    // Attach the central error-handling middleware after all routes.
    server.middlewares.use(errorHandler);
  };

  return {
    name: 'auth-plugin',
    configureServer: installWithErrorHandler,
    configurePreviewServer: installWithErrorHandler,
  };
}

/**
 * Central error handling for God's Eye View server.
 *
 * - Logs full error detail (stack, context) via the structured logger.
 * - Returns only a generic message to callers so internal detail is never leaked.
 * - Intercepts process-level uncaught exceptions and unhandled rejections.
 */
import { logger } from './logger.js';

/**
 * Express/Connect-style four-argument error-handling middleware.
 * Must be registered AFTER all normal routes:
 *   server.middlewares.use(errorHandler);
 *
 * @param {Error} err
 * @param {import('http').IncomingMessage} req
 * @param {import('http').ServerResponse} res
 * @param {Function} next
 */
export function errorHandler(err, req, res, next) {
  const status = err?.status ?? err?.statusCode ?? 500;
  logger.error(
    { event: 'request_error', path: req?.url, method: req?.method, status, err },
    'Unhandled request error',
  );
  if (res.headersSent) return next(err);
  res.writeHead(status < 600 ? status : 500, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'An unexpected error occurred. Please try again later.' }));
}

/**
 * Register process-level handlers so uncaught errors are logged centrally
 * rather than crashing silently or printing raw stack traces.
 */
export function registerProcessErrorHandlers() {
  process.on('uncaughtException', (err) => {
    logger.error({ event: 'uncaught_exception', err }, 'Uncaught exception — shutting down');
    process.exitCode = 1;
  });

  process.on('unhandledRejection', (reason) => {
    const err = reason instanceof Error ? reason : new Error(String(reason));
    logger.error({ event: 'unhandled_rejection', err }, 'Unhandled promise rejection');
  });
}

/**
 * Structured, centralised logger for God's Eye View server.
 * Attempts to load pino for production-grade NDJSON output; falls back to a
 * built-in implementation with the same API when pino is not installed.
 *
 * Usage:
 *   import { logger } from './logger.js';
 *   logger.info({ event: 'sign_in', user: 'alice' }, 'User signed in');
 *   logger.warn({ event: 'auth_failure' }, 'Bad credentials');
 *   logger.error({ err }, 'Unhandled error');
 */

function makeFallbackLogger(bindings = {}) {
  const LEVELS = { trace: 10, debug: 20, info: 30, warn: 40, error: 50, fatal: 60 };
  const minLevel = LEVELS[process.env.LOG_LEVEL] ?? LEVELS.info;

  function write(levelNum, levelName, args) {
    if (levelNum < minLevel) return;
    const [first, ...rest] = args;
    let obj = bindings;
    let msg = '';
    if (typeof first === 'string') {
      msg = first;
    } else if (first && typeof first === 'object') {
      const { err, ...fields } = first;
      obj = { ...bindings, ...fields };
      if (err instanceof Error) {
        obj.err = { message: err.message, stack: err.stack, type: err.constructor.name };
      }
      msg = typeof rest[0] === 'string' ? rest[0] : '';
    }
    const line = JSON.stringify({ level: levelNum, levelName, time: Date.now(), ...obj, msg });
    (levelNum >= LEVELS.error ? process.stderr : process.stdout).write(line + '\n');
  }

  return {
    trace: (...a) => write(10, 'trace', a),
    debug: (...a) => write(20, 'debug', a),
    info:  (...a) => write(30, 'info',  a),
    warn:  (...a) => write(40, 'warn',  a),
    error: (...a) => write(50, 'error', a),
    fatal: (...a) => write(60, 'fatal', a),
    child: (extra) => makeFallbackLogger({ ...bindings, ...extra }),
  };
}

// Attempt to load pino for structured NDJSON logging; use built-in fallback otherwise.
let _logger;
try {
  const pinoModule = await import('pino');
  const pino = pinoModule.default ?? pinoModule;
  _logger = pino({ level: process.env.LOG_LEVEL ?? 'info' });
} catch {
  _logger = makeFallbackLogger();
}

export const logger = _logger;
